package org.opensourcepingpong.competition.algorithm;
import java.util.*;
public final class SingleEliminationBracketGenerator { private SingleEliminationBracketGenerator(){} public static int bracketSize(int n){if(n<2||n>64)throw new IllegalArgumentException();int s=2;while(s<n)s*=2;return s;} public static List<Integer> seedPositions(int size){if(size<2||(size&(size-1))!=0)throw new IllegalArgumentException();List<Integer> seeds=new ArrayList<>(List.of(1,2));while(seeds.size()<size){int next=seeds.size()*2;List<Integer> expanded=new ArrayList<>();for(int seed:seeds){expanded.add(seed);expanded.add(next+1-seed);}seeds=expanded;}return seeds;} public static <T> List<T> arrange(List<T> participants,long seed){if(participants==null||new HashSet<>(participants).size()!=participants.size())throw new IllegalArgumentException("participants must be unique");int size=bracketSize(participants.size());List<T> shuffled=new ArrayList<>(participants);shuffled.sort(Comparator.comparing(Object::toString));Collections.shuffle(shuffled,new Random(seed));List<T> values=new ArrayList<>(Collections.nCopies(size,null));List<Integer> positions=seedPositions(size);for(int i=0;i<shuffled.size();i++)values.set(positions.indexOf(i+1),shuffled.get(i));return values;} }
